const t = (k, p) => {
    let s = (TXT[lang()] && TXT[lang()][k]) || TXT.en[k] || k;
    if (p) Object.keys(p).forEach(n => { s = s.split('{' + n + '}').join(p[n]); });
    return s;
};
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const toast = (m, ty) => { try { window.showToast(m, ty || 'info'); } catch (e) { /* ignore */ } };
const normPath = (p) => String(p || '').replace(/\\/g, '/');
const cur = () => { try { return (typeof printCostCurrency !== 'undefined' && printCostCurrency === 'USD') ? '$' : '€'; } catch (e) { return '€'; } };
const money = (v) => { const n = Number(v) || 0; return cur() === '$' ? '$' + n.toFixed(2) : n.toFixed(2) + ' €'; };
const pct = (v) => Math.round((Number(v) || 0) * 100);
const bytes = (n) => { n = Number(n) || 0; return n >= 1048576 ? (n / 1048576).toFixed(1) + ' Mo' : Math.max(1, Math.round(n / 1024)) + ' Ko'; };
const dateFmt = (s) => { try { const d = (typeof s === 'number') ? new Date(s * 1000) : new Date(String(s).replace(' ', 'T')); return isNaN(d) ? String(s || '') : d.toLocaleString(lang()); } catch (e) { return s; } };

async function api(method, url, body) {
    const opt = { method, credentials: 'same-origin', headers: {} };
    if (body !== undefined) { opt.headers['Content-Type'] = 'application/json'; opt.body = JSON.stringify(body); }
    let r, d = {};
    try { r = await fetch(url, opt); } catch (e) { return { ok: false, status: 0, data: { error: 'network' } }; }
    try { d = await r.json(); } catch (e) { d = {}; }
    return { ok: r.ok, status: r.status, data: d };
}

/* ---------- fenêtre modale propre ---------- */
let overlay = null;
function closeModal() { if (overlay) { overlay.remove(); overlay = null; } document.removeEventListener('keydown', onKey); }
function onKey(e) { if (e.key === 'Escape') closeModal(); }
function openModal(title, bodyHtml, wide) {
    closeModal();
    overlay = document.createElement('div');
    overlay.className = 'v13-overlay';
    overlay.innerHTML = `<div class="v13-modal${wide ? ' v13-wide' : ''}" role="dialog" aria-modal="true"><div class="v13-mh"><h3>${esc(title)}</h3><button type="button" class="v13-x" aria-label="${esc(t('close'))}">&times;</button></div><div class="v13-mb">${bodyHtml}</div></div>`;
    overlay.addEventListener('mousedown', e => { if (e.target === overlay) closeModal(); });
    $('.v13-x', overlay).addEventListener('click', closeModal);
    document.addEventListener('keydown', onKey);
    document.body.appendChild(overlay);
    return $('.v13-mb', overlay);
}

/* ---------- versions ---------- */
const ERR = { unchanged: 'v_unchanged', too_big: 'v_too_big', not_local: 'v_not_local', name_exists: 'c_name_exists' };
function errMsg(d) { return t(ERR[d && d.error] || 'err'); }

async function openVersions(path, name) {
    const mb = openModal(t('v_title', { name: name || path.split(/[\\/]/).pop() }), `<p class="v13-muted">${esc(t('v_loading'))}</p>`, true);
    async function render() {
        const r = await api('GET', '/api/versions?path=' + encodeURIComponent(path));
        if (!r.ok) { mb.innerHTML = `<p class="v13-muted">${esc(errMsg(r.data))}</p>`; return; }
        const d = r.data, vs = d.versions || [];
        const rows = vs.length ? vs.map(v => `<div class="v13-row" data-id="${v.id}">
            <div class="v13-row-main"><b>v${v.version}</b> ${v.is_current ? `<span class="v13-badge">${esc(t('v_is_current'))}</span>` : ''}${v.auto ? `<span class="v13-badge v13-badge-soft">${esc(t('v_auto'))}</span>` : ''}
            <div class="v13-muted">${esc(dateFmt(v.created_at))} · ${esc(bytes(v.size))}${v.note ? ' · ' + esc(v.note) : ''}</div></div>
            <div class="v13-row-act">
              <button type="button" class="v13-btn" data-a="cmp">${esc(t('v_compare'))}</button>
              <a class="v13-btn" href="/api/versions/${v.id}/download">${esc(t('v_download'))}</a>
              <button type="button" class="v13-btn" data-a="res">${esc(t('v_restore'))}</button>
              <button type="button" class="v13-btn v13-danger" data-a="del" title="${esc(t('delete'))}">&times;</button>
            </div></div>`).join('') : `<p class="v13-muted">${esc(t('v_none'))}</p>`;
        mb.innerHTML = `<p class="v13-muted">${esc(t('v_hint'))}</p>
          <div class="v13-form"><input type="text" class="v13-in" id="v13-note" maxlength="200" placeholder="${esc(t('v_note_ph'))}"><button type="button" class="v13-btn v13-primary" id="v13-vsave">${esc(t('v_save'))}</button></div>
          <div class="v13-list">${rows}</div><div id="v13-cmp"></div>`;
        try { window.StellioTrace && window.StellioTrace.decorate(mb, path); } catch (e) { /* ignore */ }
        $('#v13-vsave', mb).onclick = async () => {
            const x = await api('POST', '/api/versions/save', { path, note: $('#v13-note', mb).value.trim() });
            if (x.ok) { toast(t('v_saved'), 'success'); render(); } else toast(errMsg(x.data), 'error');
        };
        mb.querySelectorAll('.v13-row').forEach(row => {
            const id = Number(row.dataset.id), v = vs.find(z => z.id === id);
            row.querySelectorAll('[data-a]').forEach(b => b.onclick = async () => {
                const a = b.dataset.a;
                if (a === 'del') {
                    if (!(await showConfirmDialog(t('v_confirm_delete', { n: v.version }), { danger: true, confirmLabel: t('delete'), cancelLabel: t('cancel') }))) return;
                    const x = await api('POST', '/api/versions/delete', { id }); x.ok ? render() : toast(errMsg(x.data), 'error');
                } else if (a === 'res') {
                    if (!(await showConfirmDialog(t('v_confirm_restore', { n: v.version }), { confirmLabel: t('v_restore'), cancelLabel: t('cancel') }))) return;
                    const x = await api('POST', '/api/versions/restore', { id });
                    if (x.ok) { toast(t('v_restored'), 'success'); render(); try { loadFiles(); } catch (e) { /* ignore */ } } else toast(errMsg(x.data), 'error');
                } else if (a === 'cmp') {
                    const x = await api('GET', `/api/versions/compare?path=${encodeURIComponent(path)}&a=${id}&b=0`);
                    const box = $('#v13-cmp', mb);
                    if (!x.ok) { box.innerHTML = `<p class="v13-muted">${esc(errMsg(x.data))}</p>`; return; }
                    box.innerHTML = cmpHtml(x.data, v.version);
                    box.scrollIntoView({ block: 'nearest' });
                }
            });
        });
    }
    render();
}
function sgn(n, unit) { n = Number(n) || 0; return (n > 0 ? '+' : '') + (Math.round(n * 100) / 100) + (unit || ''); }
function cmpHtml(d, n) {
    const a = d.a, b = d.b, df = d.diff || {};
    if (df.identical) return `<div class="v13-box"><h4>${esc(t('v_cmp_title'))}</h4><p>${esc(t('v_identical'))}</p></div>`;
    const am = a.mesh, bm = b.mesh;
    const line = (lab, x, y, delta) => `<tr><td>${esc(lab)}</td><td>${x}</td><td>${y}</td><td>${delta}</td></tr>`;
    let rows = line(t('v_size'), esc(bytes(a.size)), esc(bytes(b.size)), esc(sgn((df.size || 0) / 1024, ' Ko')));
    if (am && bm) {
        rows += line(t('v_tri'), am.triangles, bm.triangles, esc(sgn(df.triangles)));
        rows += line(t('v_dim'), am.size_mm.join(' × '), bm.size_mm.join(' × '), esc((df.size_mm || []).map(x => sgn(x)).join(' / ')));
        if (am.volume_mm3 != null && bm.volume_mm3 != null) rows += line(t('v_vol'), (am.volume_mm3 / 1000).toFixed(2), (bm.volume_mm3 / 1000).toFixed(2), esc(sgn((df.volume_mm3 || 0) / 1000)));
    }
    return `<div class="v13-box"><h4>${esc(t('v_cmp_title'))}</h4><div class="v13-scroll"><table class="v13-tbl"><thead><tr><th></th><th>${esc(t('v_before'))} (v${n})</th><th>${esc(t('v_after'))} (${esc(t('v_current'))})</th><th>Δ</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
}

/* ---------- collections ---------- */
let colls = null, collsLoading = false, activeColl = null;   // activeColl = {id, name, paths:Set}
function rerenderChips() { try { window.renderSmartCollections && window.renderSmartCollections(); } catch (e) { /* ignore */ } }
async function loadColls() {
    if (collsLoading) return;
    collsLoading = true;
    const r = await api('GET', '/api/collections');
    collsLoading = false;
    colls = r.ok ? (r.data.collections || []) : [];
    if (activeColl && !colls.some(c => c.id === activeColl.id)) activeColl = null;
    rerenderChips();
}
function active() { return !!(activeColl && activeColl.paths); }
function filterFiles(files) { return files.filter(f => activeColl.paths.has(normPath(f.path))); }
function chipsHtml() {
    if (colls === null) { loadColls(); return ''; }
    const chips = colls.map(c => `<button type="button" class="sc-chip v13-chip${activeColl && activeColl.id === c.id ? ' active' : ''}" onclick="StellioV113.toggleCollection(${c.id})"><i class="fa-solid fa-layer-group"></i> ${esc(c.name)} <span class="sc-count">${c.count}</span></button>`).join('');
    return chips + `<button type="button" class="sc-chip v13-chip v13-chip-manage" onclick="StellioV113.openCollections()" title="${esc(t('c_manage'))}"><i class="fa-solid fa-${colls.length ? 'gear' : 'plus'}"></i> ${esc(colls.length ? t('c_manage') : t('c_new'))}</button>`;
}
async function toggleCollection(id) {
    if (activeColl && activeColl.id === id) { activeColl = null; try { window.applyFilters(); } catch (e) { /* ignore */ } return; }
    const r = await api('GET', '/api/collections/' + id);
    if (!r.ok) { toast(t('err'), 'error'); return; }
    activeColl = { id, name: r.data.name, paths: new Set((r.data.files || []).map(f => normPath(f.path))) };
    try { window.applyFilters(); } catch (e) { /* ignore */ }
}
async function refreshActive() {
    if (!activeColl) return;
    const r = await api('GET', '/api/collections/' + activeColl.id);
    if (r.ok) activeColl.paths = new Set((r.data.files || []).map(f => normPath(f.path)));
}

async function openCollections(openId) {
    const mb = openModal(t('c_title'), `<p class="v13-muted">${esc(t('v_loading'))}</p>`, true);
    async function list() {
        await loadColls();
        const cards = (colls || []).map(c => `<div class="v13-row v13-click" data-id="${c.id}"><div class="v13-row-main"><b><i class="fa-solid fa-layer-group"></i> ${esc(c.name)}</b>
            <div class="v13-muted">${esc(t('c_files', { n: c.count }))} · ${esc(t('c_pieces', { n: c.pieces }))}${c.description ? ' · ' + esc(c.description) : ''}</div></div>
            <div class="v13-row-act"><span class="v13-muted">›</span></div></div>`).join('') || `<p class="v13-muted">${esc(t('c_none'))}</p>`;
        mb.innerHTML = `<p class="v13-muted">${esc(t('c_hint'))}</p>
          <div class="v13-form"><input type="text" class="v13-in" id="v13-cname" maxlength="60" placeholder="${esc(t('c_name_ph'))}"><input type="text" class="v13-in" id="v13-cdesc" maxlength="200" placeholder="${esc(t('c_desc_ph'))}"><button type="button" class="v13-btn v13-primary" id="v13-ccreate">${esc(t('c_create'))}</button></div>
          <div class="v13-list">${cards}</div>`;
        $('#v13-ccreate', mb).onclick = async () => {
            const name = $('#v13-cname', mb).value.trim(); if (!name) return;
            const x = await api('POST', '/api/collections/save', { name, description: $('#v13-cdesc', mb).value.trim() });
            if (x.ok) { await list(); rerenderChips(); } else toast(errMsg(x.data), 'error');
        };
        mb.querySelectorAll('.v13-click').forEach(el => el.onclick = () => detail(Number(el.dataset.id)));
    }
    async function detail(id) {
        const r = await api('GET', '/api/collections/' + id);
        if (!r.ok) { list(); return; }
        const c = r.data, files = c.files || [];
        const rows = files.length ? files.map((f, i) => `<div class="v13-row" data-i="${i}"><div class="v13-row-main"><b>${esc(f.name)}</b> ${f.missing ? `<span class="v13-badge v13-badge-warn">${esc(t('c_missing'))}</span>` : ''}</div>
            <div class="v13-row-act"><label class="v13-muted" title="${esc(t('c_qty'))}">×<input type="number" class="v13-in v13-qty" min="1" max="999" value="${f.quantity}"></label><button type="button" class="v13-btn v13-danger" data-a="rm" title="${esc(t('c_remove'))}">&times;</button></div></div>`).join('')
            : `<p class="v13-muted">${esc(t('c_empty'))}</p>`;
        mb.innerHTML = `<div class="v13-bar"><button type="button" class="v13-btn" id="v13-back">${esc(t('c_back'))}</button><h4>${esc(c.name)}</h4></div>
          <div class="v13-form"><input type="text" class="v13-in" id="v13-ename" maxlength="60" value="${esc(c.name)}"><input type="text" class="v13-in" id="v13-edesc" maxlength="200" value="${esc(c.description)}" placeholder="${esc(t('c_desc_ph'))}"><button type="button" class="v13-btn" id="v13-esave">${esc(t('save'))}</button></div>
          <p class="v13-muted">${esc(t('c_files', { n: files.length }))} · ${esc(t('c_pieces', { n: c.pieces }))}</p>
          <div class="v13-list">${rows}</div>
          <div class="v13-form v13-end"><button type="button" class="v13-btn v13-danger" id="v13-cdel">${esc(t('delete'))}</button><button type="button" class="v13-btn v13-primary" id="v13-cq"${files.length ? '' : ' disabled'}>${esc(t('c_queue_all'))}</button></div>`;
        $('#v13-back', mb).onclick = list;
        $('#v13-esave', mb).onclick = async () => {
            const x = await api('POST', '/api/collections/save', { id, name: $('#v13-ename', mb).value.trim(), description: $('#v13-edesc', mb).value.trim(), color: c.color });
            if (x.ok) { toast(t('saved'), 'success'); loadColls(); } else toast(errMsg(x.data), 'error');
        };
        $('#v13-cdel', mb).onclick = async () => {
            if (!(await showConfirmDialog(t('c_confirm_delete', { name: c.name }), { danger: true, confirmLabel: t('delete'), cancelLabel: t('cancel') }))) return;
            const x = await api('POST', '/api/collections/delete', { id });
            if (x.ok) { if (activeColl && activeColl.id === id) { activeColl = null; try { window.applyFilters(); } catch (e) { /* ignore */ } } await list(); } else toast(t('err'), 'error');
        };
        $('#v13-cq', mb).onclick = async () => {
            const x = await api('POST', '/api/collections/queue', { id });
            if (x.ok) toast(t('c_queued', { n: x.data.added, m: x.data.already }), 'success'); else toast(t('err'), 'error');
        };
        mb.querySelectorAll('.v13-row[data-i]').forEach(row => {
            const f = files[Number(row.dataset.i)];
            $('[data-a="rm"]', row).onclick = async () => { const x = await api('POST', '/api/collections/remove-file', { id, path: f.path }); if (x.ok) { await refreshActive(); await loadColls(); detail(id); } };
            $('.v13-qty', row).onchange = async (e) => { await api('POST', '/api/collections/quantity', { id, path: f.path, quantity: Math.max(1, Math.min(999, parseInt(e.target.value, 10) || 1)) }); };
        });
    }
    if (openId) detail(openId); else list();
}

async function openAddToCollection(paths) {
    paths = (paths || []).map(normPath).filter(Boolean);
    if (!paths.length) return;
    const mb = openModal(t('c_add_to'), `<p class="v13-muted">${esc(t('v_loading'))}</p>`);
    let pick = null;
    async function draw() {
        await loadColls();
        const inn = paths.length === 1 ? await api('GET', '/api/collections/of-file?path=' + encodeURIComponent(paths[0])) : null;
        const has = new Set(((inn && inn.data.collections) || []).map(c => c.id));
        const rows = (colls || []).map(c => `<button type="button" class="v13-pick${has.has(c.id) ? ' v13-in-coll' : ''}" data-id="${c.id}"><i class="fa-solid fa-layer-group"></i> ${esc(c.name)} <span class="v13-muted">${esc(t('c_files', { n: c.count }))}</span>${has.has(c.id) ? ' <i class="fa-solid fa-check"></i>' : ''}</button>`).join('');
        mb.innerHTML = `<div class="v13-list">${rows || `<p class="v13-muted">${esc(t('c_none'))}</p>`}</div>
          <div class="v13-form"><input type="text" class="v13-in" id="v13-pname" maxlength="60" placeholder="${esc(t('c_name_ph'))}"><button type="button" class="v13-btn v13-primary" id="v13-pnew">${esc(t('c_new_here'))}</button></div>`;
        const add = async (id) => {
            const x = await api('POST', '/api/collections/add-files', { id, paths });
            if (x.ok) { toast(t('c_added', { n: x.data.added }), 'success'); await refreshActive(); await loadColls(); closeModal(); } else toast(errMsg(x.data), 'error');
        };
        mb.querySelectorAll('.v13-pick').forEach(b => b.onclick = () => add(Number(b.dataset.id)));
        $('#v13-pnew', mb).onclick = async () => {
            const name = $('#v13-pname', mb).value.trim(); if (!name) return;
            const x = await api('POST', '/api/collections/save', { name });
            if (x.ok) add(x.data.id); else toast(errMsg(x.data), 'error');
        };
    }
    draw();
}

/* ---------- statistiques d'échecs ---------- */
let failDays = 0;
function bars(groups, labelFn, minGroup) {
    if (!groups || !groups.length) return '';
    return groups.map(g => {
        const lab = labelFn(g);
        const rate = g.fail_rate == null ? null : pct(g.fail_rate);
        return `<div class="v13-bar-row"><span class="v13-bar-l" title="${esc(lab)}">${esc(lab)}</span><span class="v13-bar-t"><span class="v13-bar-f" style="width:${rate == null ? 0 : Math.max(2, rate)}%"></span></span><span class="v13-bar-v">${rate == null ? '–' : rate + ' %'} <small>(${g.failed}/${g.total})</small></span></div>`;
    }).join('');
}
function failBlock(title, groups, labelFn, d) {
    const b = bars(groups, labelFn, d.min_group);
    return b ? `<div class="v13-box"><h4>${esc(title)}</h4>${b}</div>` : '';
}
const WD = () => { const out = []; for (let i = 0; i < 7; i++) { try { out.push(new Date(2024, 0, 1 + i).toLocaleDateString(lang(), { weekday: 'long' })); } catch (e) { out.push(String(i)); } } return out; };
const HOUR_LAB = { night: 'f_night', morning: 'f_morning', afternoon: 'f_afternoon', evening: 'f_evening' };
function leadText(l) {
    const p = { key: l.key, rate: pct(l.fail_rate), base: pct(l.base_rate), failed: l.failed, total: l.total, share: pct(l.share) };
    if (l.dimension === 'reason') { p.key = l.key === '_unspecified' ? t('f_unspecified') : l.key; return t('f_lead_reason', p); }
    return t(l.dimension === 'material' ? 'f_lead_material' : l.dimension === 'printer' ? 'f_lead_printer' : 'f_lead_profile', p);
}
async function onStats() {
    const page = $('#page-stats'); if (!page) return;
    let host = $('#v13-fail');
    if (!host) { host = document.createElement('section'); host.id = 'v13-fail'; host.className = 'v13-section'; page.appendChild(host); }
    const r = await api('GET', '/api/failure-stats?days=' + failDays);
    if (!r.ok) { host.innerHTML = ''; return; }
    const d = r.data;
    const sel = [[0, 'f_all'], [30, 'f_30'], [90, 'f_90'], [365, 'f_365']].map(([v, k]) => `<button type="button" class="sc-chip${failDays === v ? ' active' : ''}" data-d="${v}">${esc(t(k))}</button>`).join('');
    let body;
    if (!d.total) body = `<p class="v13-muted">${esc(t('f_empty'))}</p>`;
    else {
        const wd = WD();
        const reasonRows = (d.by_reason || []).map(x => `<div class="v13-bar-row"><span class="v13-bar-l">${esc(x.key === '_unspecified' ? t('f_unspecified') : x.key)}</span><span class="v13-bar-t"><span class="v13-bar-f" style="width:${Math.max(2, pct(x.share))}%"></span></span><span class="v13-bar-v">${x.count} <small>(${pct(x.share)} %)</small></span></div>`).join('');
        const unk = (g) => g.key === '_unknown' ? t('unknown') : String(g.key);
        body = `<div class="v13-kpis"><div><b>${d.total}</b><span>${esc(t('f_rated'))}</span></div><div><b>${d.success}</b><span>${esc(t('f_success'))}</span></div><div><b>${d.failed}</b><span>${esc(t('f_failed'))}</span></div><div><b>${d.partial}</b><span>${esc(t('f_partial'))}</span></div><div><b>${pct(d.fail_rate)} %</b><span>${esc(t('f_rate'))}</span></div></div>`
            + ((d.leads || []).length ? `<div class="v13-box v13-leads"><h4>${esc(t('f_leads'))}</h4><ul>${d.leads.map(l => `<li>${esc(leadText(l))}</li>`).join('')}</ul></div>` : '')
            + (reasonRows ? `<div class="v13-box"><h4>${esc(t('f_reasons'))}</h4>${reasonRows}</div>` : '')
            + failBlock(t('f_material'), d.by_material, unk, d) + failBlock(t('f_printer'), d.by_printer, unk, d) + failBlock(t('f_profile'), d.by_profile, unk, d)
            + failBlock(t('f_weekday'), d.by_weekday, g => wd[g.key] || g.key, d)
            + failBlock(t('f_hour'), d.by_hour, g => t(HOUR_LAB[g.key] || 'unknown'), d)
            + ((d.worst_files || []).length ? `<div class="v13-box"><h4>${esc(t('f_worst'))}</h4>${d.worst_files.map(f => `<div class="v13-bar-row"><span class="v13-bar-l" title="${esc(f.file)}">${esc(f.file)}</span><span class="v13-bar-v">${esc(t('f_times', { n: f.failed }))} <small>/ ${f.total}</small></span></div>`).join('')}</div>` : '')
            + `<p class="v13-muted">${esc(t('f_min', { n: d.min_group }))}</p>`;
    }
    host.innerHTML = `<div class="v13-sh"><h3><i class="fa-solid fa-magnifying-glass-chart"></i> ${esc(t('f_title'))}</h3><div class="v13-chips">${sel}</div></div>${body}`;
    host.querySelectorAll('[data-d]').forEach(b => b.onclick = () => { failDays = Number(b.dataset.d); onStats(); });
}

/* ---------- réglages : tarif + Obico ---------- */
function accord(id, icon, title, inner) {
    const s = document.createElement('div');
    s.className = 'accord-section'; s.id = id;
    s.innerHTML = `<div class="accord-header" onclick="toggleAccord(this)"><span><i class="fa-solid ${icon}"></i> ${esc(title)}</span><i class="fa-solid fa-chevron-down accord-arrow"></i></div><div class="accord-body">${inner}</div>`;
    return s;
}
const E_O = { unauthorized: 'o_e_unauthorized', unreachable: 'o_e_unreachable', bad_url: 'o_e_bad_url', url_and_token_required: 'o_e_url_and_token_required' };
const obErr = (e) => t(E_O[e] || 'o_e_generic');

async function tariffSection(sec) {
    const body = $('.accord-body', sec);
    const [g, sm] = await Promise.all([api('GET', '/api/tariff'), api('GET', '/api/tariff/summary')]);
    const c = g.data || {}, s = sm.data || {};
    const sum = !sm.ok ? '' : (s.prints ? `<div class="v13-box"><h4>${esc(t('t_summary'))}</h4><p>${esc(t('t_summary_line', { prints: s.prints, kwh: s.kwh, cost: money(s.cost), share: pct(s.offpeak_share) }))}</p>${s.enabled && s.potential_saving > 0 ? `<p>${esc(t('t_saving', { saving: money(s.potential_saving) }))}</p>` : ''}</div>` : `<p class="v13-muted">${esc(t('t_none'))}</p>`);
    body.innerHTML = `<p class="v13-muted">${esc(t('t_hint'))}</p>
      <label class="v13-check"><input type="checkbox" id="v13-t-en"${c.enabled ? ' checked' : ''}> ${esc(t('t_enable'))}</label>
      <div class="v13-grid2"><label>${esc(t('t_peak'))}<input type="number" min="0" step="0.0001" class="v13-in" id="v13-t-peak" value="${c.peak_price == null ? '' : c.peak_price}"></label>
      <label>${esc(t('t_off'))}<input type="number" min="0" step="0.0001" class="v13-in" id="v13-t-off" value="${c.offpeak_price == null ? '' : c.offpeak_price}"></label></div>
      <label class="v13-block">${esc(t('t_ranges'))}<textarea class="v13-in" id="v13-t-ranges" rows="3" placeholder="22:00-06:00">${esc((c.ranges || []).join('\n'))}</textarea></label>
      <label class="v13-check"><input type="checkbox" id="v13-t-we"${c.weekend ? ' checked' : ''}> ${esc(t('t_weekend'))}</label>
      <label class="v13-check"><input type="checkbox" id="v13-t-re"${c.remind ? ' checked' : ''}> ${esc(t('t_remind'))}</label>
      ${c.enabled ? `<p class="v13-muted"><i class="fa-solid fa-bolt"></i> ${esc(t(c.offpeak_now ? 't_now_off' : 't_now_peak'))}</p>` : ''}
      <div class="v13-form"><button type="button" class="v13-btn v13-primary" id="v13-t-save">${esc(t('save'))}</button><span class="v13-muted" id="v13-t-msg"></span></div>
      ${sum}
      <div class="v13-box"><h4>${esc(t('t_sim'))}</h4><div class="v13-grid2"><label>${esc(t('t_sim_h'))}<input type="number" min="0.1" step="0.1" class="v13-in" id="v13-s-h" value="4"></label><label>${esc(t('t_sim_w'))}<input type="number" min="1" step="10" class="v13-in" id="v13-s-w" value="120"></label></div>
      <div class="v13-form"><button type="button" class="v13-btn" id="v13-s-run">${esc(t('t_sim_run'))}</button></div><div id="v13-s-out" class="v13-muted"></div></div>`;
    const msg = (m, bad) => { const e = $('#v13-t-msg', body); e.textContent = m; e.style.color = bad ? 'var(--danger,#e55353)' : ''; };
    $('#v13-t-save', body).onclick = async () => {
        const ranges = $('#v13-t-ranges', body).value.split('\n').map(x => x.trim()).filter(Boolean);
        const x = await api('POST', '/api/tariff', { enabled: $('#v13-t-en', body).checked, peak_price: $('#v13-t-peak', body).value, offpeak_price: $('#v13-t-off', body).value, ranges, weekend: $('#v13-t-we', body).checked, remind: $('#v13-t-re', body).checked });
        if (x.ok) { msg(t('saved')); tariffSection(sec); } else msg(t(x.data.error === 'bad_range' ? 't_bad_range' : x.data.error === 'price_required' ? 't_price_required' : 'err'), true);
    };
    $('#v13-s-run', body).onclick = async () => {
        const out = $('#v13-s-out', body);
        const x = await api('GET', `/api/tariff/advice?duration_s=${Math.round((parseFloat($('#v13-s-h', body).value) || 0) * 3600)}&watts=${parseFloat($('#v13-s-w', body).value) || 0}`);
        if (!x.ok) { out.textContent = t('err'); return; }
        const a = x.data; let h = esc(t('t_sim_now', { cost: money(a.now_cost), share: pct(a.now_offpeak_share) }));
        if (a.enabled) h += '<br>' + (a.offpeak_now || a.best_start == null ? esc(t('t_sim_already')) : esc(t('t_sim_best', { wait: Math.floor(a.wait_minutes / 60) + ' h ' + (a.wait_minutes % 60) + ' min', cost: money(a.best_cost), saving: money(a.saving) })));
        out.innerHTML = h;
    };
}
async function obicoSection(sec) {
    const body = $('.accord-body', sec);
    const g = await api('GET', '/api/obico'); const c = g.data || {};
    const last = c.last || {};
    const list = (last.printers || []).map(p => `<li>${esc(p.name)} — ${esc(p.alert ? t('o_alert') : p.printing ? t('o_printing') : t('o_idle'))}</li>`).join('');
    body.innerHTML = `<p class="v13-muted">${esc(t('o_hint'))}</p>
      <label class="v13-check"><input type="checkbox" id="v13-o-en"${c.enabled ? ' checked' : ''}> ${esc(t('o_enable'))}</label>
      <label class="v13-block">${esc(t('o_url'))}<input type="url" class="v13-in" id="v13-o-url" placeholder="https://obico.example.com" value="${esc(c.url || '')}"></label>
      <label class="v13-block">${esc(t('o_token'))}<input type="password" class="v13-in" id="v13-o-tok" autocomplete="new-password" placeholder="${esc(c.has_token ? t('o_token_saved') : '')}"></label>
      <label class="v13-block">${esc(t('o_interval'))}<input type="number" min="20" max="600" class="v13-in" id="v13-o-int" value="${c.interval || 60}"></label>
      <div class="v13-form"><button type="button" class="v13-btn v13-primary" id="v13-o-save">${esc(t('save'))}</button><button type="button" class="v13-btn" id="v13-o-test">${esc(t('o_test'))}</button><span class="v13-muted" id="v13-o-msg"></span></div>
      ${list ? `<ul class="v13-ul">${list}</ul>` : ''}`;
    const msg = (m, bad) => { const e = $('#v13-o-msg', body); e.textContent = m; e.style.color = bad ? 'var(--danger,#e55353)' : ''; };
    const form = () => ({ enabled: $('#v13-o-en', body).checked, url: $('#v13-o-url', body).value.trim(), token: $('#v13-o-tok', body).value.trim(), interval: parseInt($('#v13-o-int', body).value, 10) || 60 });
    $('#v13-o-save', body).onclick = async () => { const x = await api('POST', '/api/obico', form()); x.ok ? (msg(t('saved')), obicoSection(sec)) : msg(obErr(x.data.error), true); };
    $('#v13-o-test', body).onclick = async () => {
        const f = form(); msg('…');
        const x = await api('POST', '/api/obico/test', { url: f.url, token: f.token });
        x.data && x.data.ok ? msg(t('o_ok', { n: (x.data.printers || []).length })) : msg(obErr(x.data && x.data.error), true);
    };
}
let settingsDone = false;
function onSettings() {
    if (settingsDone && $('#v13-tariff-section')) return;
    const first = $('#page-settings .accord-section'); if (!first) return;
    const tsec = accord('v13-tariff-section', 'fa-bolt', t('t_title'), `<p class="v13-muted">${esc(t('v_loading'))}</p>`);
    const osec = accord('v13-obico-section', 'fa-eye', t('o_title'), `<p class="v13-muted">${esc(t('v_loading'))}</p>`);
    first.parentNode.insertBefore(tsec, first); first.parentNode.insertBefore(osec, first);
    settingsDone = true;
    tariffSection(tsec); obicoSection(osec);
    try { window.balanceSettingsColumns && window.balanceSettingsColumns(); } catch (e) { /* ignore */ }
}

/* ---------- inventaire de résine (bêta) ---------- */
let resinState = { bottles: [], kinds: [] };
let resinOrders = [];
const KINDS = ['standard', 'abs_like', 'tough', 'flexible', 'water_washable', 'castable', 'dental', 'high_temp', 'other'];
const kindLabel = (k) => t(`k_${k}`);
const fmtMl = (n) => String(Math.round((Number(n) || 0) * 10) / 10);
async function onResin() {
    const host = $('#v13-resin-host'); if (!host) return;
    const [r, rs] = await Promise.all([api('GET', '/api/resin'), api('GET', '/api/resin/restock')]);
    if (!r.ok) { host.innerHTML = `<p class="v13-muted">${esc(t('err'))}</p>`; return; }
    resinState = r.data;
    const orders = (rs.ok && rs.data.items) || [];
    resinOrders = orders;
    const lowIds = new Set(); orders.filter(o => !o.manual).forEach(o => (o.ids || []).forEach(i => lowIds.add(i)));
    const thr = rs.ok ? rs.data.threshold_ml : 200;
    const bs = r.data.bottles || [];
    const cards = bs.map(b => {
        const pctLeft = b.volume_ml > 0 ? Math.max(0, Math.min(100, Math.round(b.remaining_ml / b.volume_ml * 100))) : 0;
        return `<div class="v13-bottle" data-id="${b.id}">
          <div class="v13-bottle-top"><span class="v13-swatch" style="background:${esc(b.color_hex || 'var(--bg-hover)')}"></span>
            <div class="v13-bottle-name"><b>${esc(b.name)}</b>${lowIds.has(b.id) ? ` <span class="v13-low">${esc(t('r_low'))}</span>` : ''}<div class="v13-muted">${esc([b.brand, kindLabel(b.kind)].filter(Boolean).join(' · '))}</div></div></div>
          <div class="v13-bar-t"><span class="v13-bar-f v13-bar-ok" style="width:${pctLeft}%"></span></div>
          <div class="v13-muted">${esc(t('r_left', { ml: fmtMl(b.remaining_ml), total: fmtMl(b.volume_ml) }))}</div>
          ${b.location || b.price != null ? `<div class="v13-muted">${esc([b.location, b.price != null ? money(b.price) : ''].filter(Boolean).join(' · '))}</div>` : ''}
          ${b.notes ? `<div class="v13-muted">${esc(b.notes)}</div>` : ''}
          <label class="v13-flag"><input type="checkbox" data-a="flag"${b.to_order ? ' checked' : ''}> ${esc(t('r_flag'))}</label>
          <div class="v13-row-act"><button type="button" class="v13-btn" data-a="use">${esc(t('r_use'))}</button><button type="button" class="v13-btn" data-a="edit">${esc(t('r_edit'))}</button><button type="button" class="v13-btn v13-danger" data-a="del" title="${esc(t('delete'))}">&times;</button></div></div>`;
    }).join('');
    host.innerHTML = `<div class="v13-sh"><h3><i class="fa-solid fa-droplet"></i> ${esc(t('r_title'))} <span class="beta-badge">${esc(t('r_beta'))}</span></h3>
        <div class="v13-chips"><span class="v13-muted">${esc(t('r_total', { ml: fmtMl(r.data.total_remaining_ml) }))}</span><button type="button" class="v13-btn v13-primary" id="v13-r-add"><i class="fa-solid fa-plus"></i> ${esc(t('r_add'))}</button></div></div>
        <p class="v13-muted">${esc(t('r_hint'))}</p>
        <label class="v13-muted v13-thr">${esc(t('r_threshold'))} <input type="number" min="0" step="10" class="v13-in" id="v13-r-thr" value="${esc(thr)}"></label>
        ${orders.length ? `<div class="v13-orders"><h4><i class="fa-solid fa-cart-shopping"></i> ${esc(t('r_order_title'))}</h4>${orders.map((o, i) => `<div class="v13-order" data-i="${i}">
          <span class="v13-swatch" style="background:${esc(o.color_hex || '#888')}"></span>
          <div class="v13-bottle-name"><b>${esc([o.vendor, o.name].filter(Boolean).join(' '))}</b><div class="v13-muted">${esc(t('r_ml_left', { ml: fmtMl(o.total_ml) }))}${o.bottle_count ? ' · ' + esc(t('r_bottles_n', { n: o.bottle_count })) : ''}</div></div>
          <button type="button" class="v13-btn v13-primary" data-a="order">${esc(t('r_order_btn'))}</button><button type="button" class="v13-btn" data-a="done">${esc(t('r_ordered'))}</button></div>`).join('')}</div>` : ''}
        ${bs.length ? `<div class="v13-bottles">${cards}</div>` : `<p class="v13-muted">${esc(t('r_none'))}</p>`}`;
    $('#v13-r-add', host).onclick = () => resinForm(null);
    $('#v13-r-thr', host).onchange = async (e) => { const x = await api('POST', '/api/resin/restock/threshold', { ml: e.target.value }); x.ok ? onResin() : toast(rErr(x.data), 'error'); };
    host.querySelectorAll('.v13-order').forEach(el => {
        const o = orders[Number(el.dataset.i)];
        $('[data-a="order"]', el).onclick = () => resinShops(o);
        $('[data-a="done"]', el).onclick = async () => { const x = await api('POST', '/api/resin/restock/snooze', { key: o.key, days: 14 }); if (x.ok) { toast(t('r_ordered_ok'), 'success'); onResin(); } else toast(t('err'), 'error'); };
    });
    host.querySelectorAll('.v13-bottle').forEach(el => {
        const b = bs.find(x => x.id === Number(el.dataset.id));
        $('[data-a="edit"]', el).onclick = () => resinForm(b);
        $('[data-a="use"]', el).onclick = () => resinUse(b);
        $('[data-a="flag"]', el).onchange = async (e) => { const x = await api('POST', '/api/resin/restock/flag', { id: b.id, flagged: e.target.checked }); x.ok ? onResin() : toast(t('err'), 'error'); };
        $('[data-a="del"]', el).onclick = async () => { if (!(await showConfirmDialog(t('r_confirm_delete'), { danger: true, confirmLabel: t('delete'), cancelLabel: t('cancel') }))) return; const x = await api('POST', '/api/resin/delete', { id: b.id }); x.ok ? onResin() : toast(t('err'), 'error'); };
    });
}
const rErr = (d) => { const k = 'r_e_' + (d && d.error); return (TXT.en[k]) ? t(k) : t('err'); };
function resinForm(b) {
    const v = b || { name: '', brand: '', kind: 'standard', color_hex: '#4ea1d3', volume_ml: 1000, remaining_ml: 1000, price: '', location: '', notes: '' };
    const mb = openModal(b ? t('r_edit') : t('r_add'), `
      <label class="v13-block">${esc(t('r_name'))}<input class="v13-in" id="v13-f-name" maxlength="120" value="${esc(v.name)}"></label>
      <div class="v13-grid2"><label>${esc(t('r_brand'))}<input class="v13-in" id="v13-f-brand" maxlength="80" value="${esc(v.brand)}"></label>
        <label>${esc(t('r_kind'))}<select class="v13-in" id="v13-f-kind">${KINDS.map(k => `<option value="${k}"${v.kind === k ? ' selected' : ''}>${esc(kindLabel(k))}</option>`).join('')}</select></label></div>
      <div class="v13-grid2"><label>${esc(t('r_volume'))}<input type="number" min="1" step="1" class="v13-in" id="v13-f-vol" value="${esc(v.volume_ml)}"></label>
        <label>${esc(t('r_remaining'))}<input type="number" min="0" step="1" class="v13-in" id="v13-f-rem" value="${esc(v.remaining_ml)}"></label></div>
      <div class="v13-grid2"><label>${esc(t('r_price'))} (${cur()})<input type="number" min="0" step="0.01" class="v13-in" id="v13-f-price" value="${v.price == null ? '' : esc(v.price)}"></label>
        <label>${esc(t('r_color'))}<input type="color" class="v13-in v13-color" id="v13-f-color" value="${esc(v.color_hex || '#4ea1d3')}"></label></div>
      <label class="v13-block">${esc(t('r_location'))}<input class="v13-in" id="v13-f-loc" maxlength="80" value="${esc(v.location)}"></label>
      <label class="v13-block">${esc(t('r_notes'))}<textarea class="v13-in" id="v13-f-notes" rows="2" maxlength="500">${esc(v.notes)}</textarea></label>
      <div class="v13-form v13-end"><span class="v13-muted" id="v13-f-msg" style="color:var(--danger,#e55353)"></span><button type="button" class="v13-btn v13-primary" id="v13-f-save">${esc(t('save'))}</button></div>`);
    $('#v13-f-save', mb).onclick = async () => {
        const body = { name: $('#v13-f-name', mb).value, brand: $('#v13-f-brand', mb).value, kind: $('#v13-f-kind', mb).value, volume_ml: $('#v13-f-vol', mb).value,
            remaining_ml: $('#v13-f-rem', mb).value, price: $('#v13-f-price', mb).value, color_hex: $('#v13-f-color', mb).value, location: $('#v13-f-loc', mb).value, notes: $('#v13-f-notes', mb).value };
        if (b) body.id = b.id;
        const x = await api('POST', '/api/resin/save', body);
        if (x.ok) { closeModal(); onResin(); } else $('#v13-f-msg', mb).textContent = rErr(x.data);
    };
}
function resinShops(o) {
    const shops = o.shops || [];
    const mb = openModal(t('r_shops_title', { name: [o.vendor, o.name].filter(Boolean).join(' ') }), `<p class="v13-muted">${esc(t('r_shops_note'))}</p>` +
        (shops.length ? shops.map((sh, i) => `<a class="v13-btn v13-shop" href="${esc(sh.url)}" target="_blank" rel="noopener noreferrer"><i class="fa-solid ${sh.brand ? 'fa-industry' : 'fa-store'}"></i> ${esc(sh.name)}</a>`).join('') : `<p class="v13-muted">${esc(t('r_no_shop'))}</p>`));
    return mb;
}
function resinUse(b) {
    const mb = openModal(t('r_use') + ' — ' + b.name, `<label class="v13-block">${esc(t('r_use_ml'))}<input type="number" min="1" step="1" class="v13-in" id="v13-u-ml" value="50"></label>
      <div class="v13-form v13-end"><span class="v13-muted" id="v13-u-msg" style="color:var(--danger,#e55353)"></span><button type="button" class="v13-btn v13-primary" id="v13-u-ok">${esc(t('r_use'))}</button></div>`);
    $('#v13-u-ok', mb).onclick = async () => {
        const x = await api('POST', '/api/resin/use', { id: b.id, ml: $('#v13-u-ml', mb).value });
        if (x.ok) { closeModal(); onResin(); } else $('#v13-u-msg', mb).textContent = rErr(x.data);
    };
}

